package norm

import "testing"

func TestNormalizeLowercasesAndCollapses(t *testing.T) {
	if got := Normalize("  Hello   World  "); got != "hello world" {
		t.Fatalf("got %q", got)
	}
}

func TestNormalizeKeepsPunctuation(t *testing.T) {
	if got := Normalize("Hello, World!"); got != "hello, world!" {
		t.Fatalf("got %q", got)
	}
}

