package report

import (
	"strings"

	"example.com/textpipe/norm"
)

// Render joins the normalised titles with "; ".
func Render(titles []string) string {
	out := make([]string, 0, len(titles))
	for _, t := range titles {
		n := norm.Normalize(t)
		if n == "" {
			continue
		}
		out = append(out, n)
	}
	return strings.Join(out, "; ")
}

