package index

import (
	"sort"
	"strings"

	"example.com/textpipe/norm"
)

// Build maps each normalised word to the sorted document numbers it
// appears in.
func Build(docs []string) map[string][]int {
	out := map[string][]int{}
	for i, d := range docs {
		seen := map[string]bool{}
		for _, w := range strings.Split(norm.Normalize(d), " ") {
			if w == "" || seen[w] {
				continue
			}
			seen[w] = true
			out[w] = append(out[w], i)
		}
	}
	for _, v := range out {
		sort.Ints(v)
	}
	return out
}

