package index

import (
	"reflect"
	"testing"
)

func TestBuild(t *testing.T) {
	got := Build([]string{"Go  is Fun", "go go go"})
	if !reflect.DeepEqual(got["go"], []int{0, 1}) {
		t.Fatalf("go = %v", got["go"])
	}
	if !reflect.DeepEqual(got["fun"], []int{0}) {
		t.Fatalf("fun = %v", got["fun"])
	}
}

